subtopics.example:
let a = 5;
console.log(a++); // 5 (returns old, then a becomes 6)
console.log(++a); // 7 (increments first, then returns)

const user = null;
console.log(user && user.name); // null — never reads .name, no crash
console.log(user || 'Guest'); // 'Guest'

const age = 20;
const status = age >= 18 ? 'adult' : 'minor';
console.log(status); // 'adult'

const count = 0;
console.log(count || 10); // 10 — 0 is falsy, wrongly replaced
console.log(count ?? 10); // 0 — only replaces null/undefined

