solution.code:
function getSetting(config, key, fallback) {
  return config?.[key] ?? fallback;
}

console.log(getSetting({ volume: 0 }, 'volume', 5)); // 0
console.log(getSetting({}, 'volume', 5)); // 5
console.log(getSetting(null, 'volume', 5)); // 5

brokenCode.code:
function getQuantity(input) {
  return input || 1; // default to 1 if not provided
}

console.log(getQuantity(0)); // expected 0, but logs 1
console.log(getQuantity(undefined)); // 1 (correct)

solution.code:
function getQuantity(input) {
  return input ?? 1; // only default when null/undefined
}

console.log(getQuantity(0)); // 0
console.log(getQuantity(undefined)); // 1

function fizzbuzz(n) {
  const byThree = n % 3 === 0;
  const byFive = n % 5 === 0;
  if (byThree && byFive) return 'FizzBuzz';
  if (byThree) return 'Fizz';
  if (byFive) return 'Buzz';
  return n;
}

console.log(fizzbuzz(15)); // 'FizzBuzz'
console.log(fizzbuzz(9));  // 'Fizz'
console.log(fizzbuzz(10)); // 'Buzz'
console.log(fizzbuzz(7));  // 7
